<?php
/** TEMP PS S1620 run e4d2 (v1.1 → v1.2) — R: WC verify-email msgid + vertimai vieta/md5 · D: vertimai v1.0 → v1.1 (md5 sargas, kopija, token_get_all, ping-atkūrimas) · Q: versija + svečio puslapio tekstas. */
add_action('init', function(){
  if (!isset($_GET['ps_e4d2'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e4d2'])); $o=array('v'=>'S1620 e4d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(200);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  $ping=function(){ $r=wp_remote_get(admin_url('admin-ajax.php?action=heartbeat'),array('timeout'=>90,'sslverify'=>false)); $b=(string)wp_remote_retrieve_body($r); return array('code'=>wp_remote_retrieve_response_code($r),'fatal'=>(int)(stripos($b,'Fatal error')!==false||stripos($b,'Parse error')!==false)); };
  $fp=file_exists(WPMU_PLUGIN_DIR.'/petshop-vertimai.php')?WPMU_PLUGIN_DIR.'/petshop-vertimai.php':WP_PLUGIN_DIR.'/petshop-vertimai/petshop-vertimai.php'; $up=wp_upload_dir(); $bk=$up['basedir'].'/ps-backups/petshop-vertimai-v11-BACKUP-2026-09-06.php';
  $svecio=function(){ $g=wc_get_order(35813); $r=wp_remote_get($g->get_checkout_order_received_url(),array('timeout'=>90,'sslverify'=>false)); $h=preg_replace('#<(script|style)\b.*?</\1>#si',' ',(string)wp_remote_retrieve_body($r)); preg_match('#<main\b.*?</main>#si',$h,$m); return mb_substr(trim(preg_replace('/\s+/',' ',html_entity_decode(wp_strip_all_tags($m[0]??$h),ENT_QUOTES,'UTF-8'))),0,400); };
  try{
  if($f==='R'){ $o['fp']=$fp; $o['yra']=file_exists($fp); $o['md5']=file_exists($fp)?md5_file($fp):null; $o['klase']=class_exists('Petshop_Vertimai'); $t=(string)file_get_contents(WP_PLUGIN_DIR.'/woocommerce/templates/checkout/form-verify-email.php'); $o['msgid']=preg_match_all("/__\(\s*'([^']+)'\s*,\s*'woocommerce'/",$t,$mm)?$mm[1]:null; $o['svecio_pries']=$svecio(); $J($o); }
  if($f==='D'){
    $t=(string)file_get_contents(WP_PLUGIN_DIR.'/woocommerce/templates/checkout/form-verify-email.php'); if(strpos($t,'To view this page, you must either %1$slogin%2$s or verify the email address associated with the order.')===false){ $o['STOP']='WC msgid kitoks'; $J($o); }
    $live=(string)file_get_contents($fp); $o['md5_pries']=md5($live); if(md5($live)!=='69c355719521fa9eaa09b8f4fcb99725'){ $o['STOP']='gyvo md5 nesutampa'; $J($o); }
    $n=base64_decode('',true); if($n===false||md5($n)!=='8654dcc7c5445b477b19c7b4c23d1637'){ $o['STOP']='b64/md5 naujo'; $J($o); }
    try{ token_get_all($n,TOKEN_PARSE); }catch(Throwable $e){ $o['STOP']='token: '.$e->getMessage(); $J($o); }
    if(!is_dir(dirname($bk))) wp_mkdir_p(dirname($bk)); $o['kopija']=(int)file_put_contents($bk,$live);
    $o['irasyta']=(int)file_put_contents($fp,$n); if(function_exists('opcache_invalidate')) opcache_invalidate($fp,true);
    $o['ping']=$ping(); if($o['ping']['fatal']||$o['ping']['code']>=500){ file_put_contents($fp,$live); $o['ATKURTA']=md5_file($fp); }
    $o['md5_po']=md5_file($fp); $J($o);
  }
  if($f==='Q'){ $o['md5']=md5_file($fp); $o['apimtis']=class_exists('Petshop_Vertimai')?Petshop_Vertimai::apimtis():null; $o['ping']=$ping(); $o['svecio_po']=$svecio(); $o['tr']=array(__('We were unable to verify the email address you provided. Please try again.','woocommerce'),__('To view this page, you must either %1$slogin%2$s or verify the email address associated with the order.','woocommerce')); $o['temp_liko']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}snippets WHERE name LIKE 'TEMP%'"); $J($o); }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.basename($e->getFile()).':'.$e->getLine(); }
  $J($o);
},99);
